import re
files = ["skill-asset-template.md","skill-md-template.md","skill-procedure-template.md","skill-readme-template.md","skill-reference-template.md","skill-router-template.md","skill-scaffold-template.md","skill-smart-router.md"]
for f in files:
    lines=open(f).read().splitlines()
    fence=None; block=[]; start=0; bad=[]
    def check(block,start):
        if len(block)<2: return
        counts=[l.count('|') for l in block]
        if len(set(counts))>1:
            bad.append((start,counts))
    for i,l in enumerate(lines,1):
        m=re.match(r'^(`{3,}|~{3,})', l.strip())
        if m:
            ch=m.group(1)[0]; n=len(m.group(1))
            if fence is None: fence=(ch,n)
            elif ch==fence[0] and n>=fence[1]: fence=None
            if block: check(block,start); block=[]
            continue
        if fence: continue
        if l.strip().startswith('|'):
            if not block: start=i
            block.append(l)
        else:
            if block: check(block,start); block=[]
    if block: check(block,start)
    for s,c in bad: print(f"{f}: table starting {s} col-counts {c}")
